/* One prospect record powers its list, pipeline and insight views. */
let prospectHubTab='pipeline',prospectHubQuery='',prospectHubOwner='all',prospectHubFollowup='all',prospectHubSort='followup',prospectHubRange='30',prospectHubSelectedView='';
let prospectFullscreen=false;
function prospectHubSaveView(){modal('Save prospect view','Keep the current pipeline filters and sort order for later.',`<form id="prospect-save-view-form"><div class="field"><label for="prospect-view-name">View name *</label><input id="prospect-view-name" name="name" required maxlength="40" placeholder="e.g. Follow-ups this week"></div></form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary" type="submit" form="prospect-save-view-form">Save view</button>`);}
let prospectListSort='followup',prospectListPage=1,prospectListPageSize=10;
const prospectHubStages=['New','Contacted','Discovery','Qualified','Proposal','Negotiation','Lost','Converted'];
for(const [index,lead] of state.leads.entries())if(!lead.createdAt)lead.createdAt=localDate(-(index*12+2));
if(!state.prospectViews)state.prospectViews=[];
save();
function renderProspectHub(){return `<div class="prospect-hub"><div class="prospect-hub-tabs" role="tablist" aria-label="Prospect views"><button role="tab" aria-selected="${prospectHubTab==='pipeline'}" data-prospect-tab="pipeline">Pipeline</button><button role="tab" aria-selected="${prospectHubTab==='insights'}" data-prospect-tab="insights">Insights</button>${prospectHubTab==='pipeline'?`<button class="prospect-expand" data-prospect-action="fullscreen" aria-pressed="${prospectFullscreen}">${prospectFullscreen?'Exit full screen':'Full screen'}</button>`:''}</div>${prospectHubTab==='insights'?renderProspectInsights():renderProspectPipeline()}</div>`;}
function prospectFollowupMatch(lead){
 if(prospectHubFollowup==='all')return true;
 if(['Lost','Converted'].includes(lead.stage))return false;
 const date=String(lead.nextFollowUp||''),today=opsToday();
 if(prospectHubFollowup==='missing')return !date;
 if(!date)return false;
 if(prospectHubFollowup==='overdue')return date<today;
 if(prospectHubFollowup==='today')return date===today;
 return prospectHubFollowup==='next7'&&date>=today&&date<=localDate(7);
}
function prospectHubRows(){const q=prospectHubQuery.toLowerCase(),rows=state.leads.filter(l=>(prospectHubOwner==='all'||l.owner===prospectHubOwner)&&prospectFollowupMatch(l)&&[l.name,l.contact,l.email,l.city,...(l.interestedProducts||[]).map(id=>nameOf('products',id))].some(v=>String(v||'').toLowerCase().includes(q)));rows.sort((a,b)=>prospectHubSort==='name'?a.name.localeCompare(b.name):prospectHubSort==='recent'?String(b.createdAt||'').localeCompare(a.createdAt||''):String(a.nextFollowUp||'9999').localeCompare(b.nextFollowUp||'9999'));return rows;}
function renderProspectPipeline(){const rows=prospectHubRows(),owners=[...new Set(state.leads.map(l=>l.owner).filter(Boolean))].sort();return `<div class="ops-page prospect-pipeline"><div class="ops-heading"><div><h1>Prospect pipeline</h1><p>Move an institution through sales stages; each card is the prospect record.</p></div><button class="btn btn-primary" data-prospect-action="new">${icon('plus')}Add prospect</button></div><section class="ops-surface ops-pipeline-shell"><div class="ops-toolbar"><input type="search" data-prospect-input="query" aria-label="Search pipeline prospects" placeholder="Search institutions or contacts" value="${esc(prospectHubQuery)}"><select data-prospect-change="owner" aria-label="Filter pipeline by owner">${opsOption('all','All owners',prospectHubOwner)}${owners.map(x=>opsOption(x,x,prospectHubOwner)).join('')}</select><select data-prospect-change="followup" aria-label="Filter pipeline by follow-up">${[['all','All follow-ups'],['overdue','Overdue'],['today','Due today'],['next7','Next 7 days'],['missing','No date']].map(([a,b])=>opsOption(a,b,prospectHubFollowup)).join('')}</select><select data-prospect-change="sort" aria-label="Sort pipeline prospects">${[['followup','Follow-up date'],['recent','Recently added'],['name','Institution A–Z']].map(([a,b])=>opsOption(a,b,prospectHubSort)).join('')}</select><select data-prospect-change="saved" aria-label="Saved prospect views">${opsOption('','Saved views',prospectHubSelectedView)}${state.prospectViews.map(v=>opsOption(v.id,v.name,prospectHubSelectedView)).join('')}</select><button class="ops-quiet-button" data-prospect-action="save-view">Save view</button>${prospectHubSelectedView?'<button class="ops-quiet-button" data-prospect-action="delete-view">Remove</button>':''}</div>${rows.length?`<div class="ops-board" aria-label="Prospect stage board">${prospectHubStages.map(stage=>{const leads=rows.filter(l=>l.stage===stage);return `<section class="ops-lane prospect-lane" data-prospect-stage="${stage}" aria-label="${stage} prospects"><div class="ops-lane-head"><div><span class="ops-stage-dot"></span><strong>${stage}</strong><span>${leads.length}</span></div><small>${stage==='Converted'?'Client created':stage==='Lost'?'Closed opportunities':'Active prospects'}</small></div><div class="ops-lane-body">${leads.map(l=>`<article class="prospect-card" draggable="${l.stage==='Converted'?'false':'true'}" data-prospect-id="${l.id}"><button class="prospect-card-main" data-prospect-action="detail" data-id="${l.id}"><span class="prospect-card-kicker">${esc(l.type||'Institution')}</span><strong>${esc(l.name)}</strong><small>${esc(l.contact||'No contact')} · ${l.nextFollowUp?prettyDate(l.nextFollowUp):'No follow-up set'}</small></button><div class="prospect-card-products">${(l.interestedProducts||[]).slice(0,2).map(pid=>`<span>${esc(nameOf('products',pid))}</span>`).join('')||'<span>No products yet</span>'}</div><div class="prospect-card-foot"><span>${esc(initials(l.owner||'U'))}</span>${esc(l.owner||'Unassigned')}</div></article>`).join('')||'<p class="ops-lane-empty">No prospects here</p>'}</div></section>`}).join('')}</div>`:opsEmpty('No prospects match','Change the filters or add an institution.',`<button class="btn btn-primary" data-prospect-action="new">Add prospect</button>`)}</section></div>`;}
function renderProspectInsights(){const cutoff=prospectHubRange==='0'?'':localDate(-Number(prospectHubRange)),rows=state.leads.filter(l=>!cutoff||String(l.createdAt||opsToday())>=cutoff),active=rows.filter(l=>!['Lost','Converted'].includes(l.stage)),converted=rows.filter(l=>l.stage==='Converted'),overdue=active.filter(l=>l.nextFollowUp&&l.nextFollowUp<opsToday()),counts=prospectHubStages.map(stage=>({stage,count:rows.filter(l=>l.stage===stage).length})),max=Math.max(1,...counts.map(x=>x.count));return `<div class="ops-page prospect-insights"><div class="ops-heading"><div><h1>Prospect insights</h1><p>Counts and follow-ups from the same prospect records shown in the pipeline.</p></div><div class="ops-date-tabs" role="group" aria-label="Prospect date range">${[['7','7 days'],['30','30 days'],['90','90 days'],['0','All time']].map(([value,label])=>`<button data-prospect-action="range" data-value="${value}" class="${prospectHubRange===value?'active':''}" aria-pressed="${prospectHubRange===value}">${label}</button>`).join('')}</div></div><div class="ops-metrics"><article><small>Active prospects</small><strong>${active.length}</strong><span>In an open sales stage</span></article><article><small>Converted</small><strong>${converted.length}</strong><span>${rows.length?Math.round(converted.length/rows.length*100):0}% of prospects in period</span></article><article><small>Overdue follow-ups</small><strong>${overdue.length}</strong><span>Need an owner action</span></article></div><div class="ops-insight-grid"><section class="ops-surface ops-chart"><div class="ops-section-head"><h2>Prospects by stage</h2><span>${rows.length} total</span></div>${rows.length?`<div class="ops-bars" role="img" aria-label="${counts.map(x=>x.stage+': '+x.count).join(', ')}">${counts.map(x=>`<div><span class="ops-bar-value">${x.count}</span><div class="ops-bar-track"><span style="height:${Math.max(4,x.count/max*100)}%"></span></div><small>${x.stage}</small></div>`).join('')}</div>`:opsEmpty('No prospects in this period','Choose a wider date range or add a prospect.')}</section><section class="ops-surface ops-insight-list"><div class="ops-section-head"><h2>Follow up next</h2><button data-prospect-tab="pipeline">Open pipeline →</button></div>${active.sort((a,b)=>String(a.nextFollowUp||'9999').localeCompare(b.nextFollowUp||'9999')).slice(0,5).map(l=>`<button data-prospect-action="detail" data-id="${l.id}"><span><strong>${esc(l.name)}</strong><small>${esc(l.owner||'Unassigned')} · ${l.nextFollowUp?prettyDate(l.nextFollowUp):'No date'}</small></span><b>${esc(l.stage)}</b></button>`).join('')||opsEmpty('No active prospects','Add a prospect to plan the next follow-up.')}</section></div></div>`;}
function prospectHubDrawer(id){const l=byId('leads',id);if(!l)return;const stageSelect=l.stage==='Converted'?`<strong>Converted to client</strong>`:`<select data-prospect-change="stage" data-id="${l.id}" aria-label="Change prospect stage">${leadStages.map(x=>opsOption(x,x,l.stage)).join('')}</select>`;$('#modal-root').innerHTML=`<div class="ops-drawer-backdrop" data-prospect-action="drawer-close"><aside class="ops-drawer" role="dialog" aria-modal="true" aria-label="${esc(l.name)} prospect details"><div class="ops-drawer-top"><span>PROSPECT</span><button data-prospect-action="drawer-close" aria-label="Close prospect details">×</button></div><h2>${esc(l.name)}</h2><p class="ops-drawer-company">${esc(l.type||'Institution')} · ${esc(l.city||'City not set')}</p><div class="prospect-drawer-products">${(l.interestedProducts||[]).map(pid=>`<span>${esc(nameOf('products',pid))}</span>`).join('')||'<span>No products selected</span>'}</div><div class="ops-drawer-fields"><label>Stage${stageSelect}</label><div><small>Owner</small><strong>${esc(l.owner||'Unassigned')}</strong></div><div><small>Contact</small><strong>${esc(l.contact||'—')}</strong></div><div><small>Next follow-up</small><strong>${prettyDate(l.nextFollowUp)}</strong></div></div><div class="ops-drawer-notes"><h3>Next action</h3><p>${esc(l.nextAction||'No next action set.')}</p><h3>Notes</h3><p>${esc(l.notes||'No notes yet.')}</p></div><div class="ops-drawer-actions"><button class="btn btn-primary" data-prospect-action="open-record" data-id="${l.id}">Open prospect</button>${l.stage!=='Converted'?`<button class="btn" data-prospect-action="edit" data-id="${l.id}">Edit & assign</button>`:''}</div></aside></div>`;$('#modal-root .ops-drawer-actions')?.insertAdjacentHTML('beforeend',`<button class="btn btn-danger" data-action="delete-prospect" data-id="${esc(l.id)}">Delete prospect</button>`);$('#modal-root .ops-drawer button')?.focus();}
function prospectHubMove(id,stage){const l=byId('leads',id);if(!l||l.stage==='Converted'||!leadStages.includes(stage)||l.stage===stage)return;if(stage==='Lost'){modal('Close prospect as lost','Record why this opportunity closed.',`<form id="prospect-loss-form" data-id="${id}"><div class="field"><label for="prospect-loss-reason">Reason *</label><textarea id="prospect-loss-reason" name="reason" required minlength="8" placeholder="Reason for closing this prospect"></textarea></div></form>`,`<button class="btn" data-action="close-modal">Cancel</button><button class="btn btn-primary" type="submit" form="prospect-loss-form">Mark lost</button>`);return;}const previous=l.stage;l.stage=stage;if(previous==='Lost')l.lossReason='';(l.history||(l.history=[])).push({at:new Date().toLocaleString('en-IN'),text:`Stage: ${previous} → ${stage}`});save();render();toast(`${l.name} moved to ${stage}.`);}
document.addEventListener('click',event=>{const tab=event.target.closest('[data-prospect-tab]');if(tab){prospectHubTab=tab.dataset.prospectTab;if(prospectHubTab!=='pipeline'){prospectFullscreen=false;document.body.classList.remove('prospect-fullscreen');}filter='';render();return;}const button=event.target.closest('[data-prospect-action]');if(!button)return;const action=button.dataset.prospectAction,id=button.dataset.id;if(action==='new')openForm('lead');else if(action==='detail')prospectHubDrawer(id);else if(action==='open-record'){selectedLeadId=id;$('#modal-root').innerHTML='';setView('leadDetail');}else if(action==='edit')openLeadEditor(id);else if(action==='drawer-close'){if(event.target===button||button.tagName==='BUTTON')$('#modal-root').innerHTML='';}else if(action==='range'){prospectHubRange=button.dataset.value;render();}else if(action==='save-view'){prospectHubSaveView();}else if(action==='delete-view'){state.prospectViews=state.prospectViews.filter(v=>v.id!==prospectHubSelectedView);prospectHubSelectedView='';save();render();toast('Prospect view removed.');}},true);
document.addEventListener('input',event=>{if(event.target.dataset.prospectInput!=='query')return;const cursor=event.target.selectionStart;prospectHubQuery=event.target.value;render();const input=$('[data-prospect-input="query"]');input?.focus();input?.setSelectionRange(cursor,cursor);},true);
document.addEventListener('change',event=>{const key=event.target.dataset.prospectChange;if(!key)return;if(key==='owner')prospectHubOwner=event.target.value;if(key==='sort')prospectHubSort=event.target.value;if(key==='followup')prospectHubFollowup=event.target.value;if(key==='saved'){prospectHubSelectedView=event.target.value;const saved=state.prospectViews.find(v=>v.id===prospectHubSelectedView);if(saved){prospectHubQuery=saved.query;prospectHubOwner=saved.owner;prospectHubSort=saved.sort;prospectHubFollowup=saved.followup||'all';}}if(key==='stage'){const id=event.target.dataset.id,stage=event.target.value;$('#modal-root').innerHTML='';prospectHubMove(id,stage);return;}render();},true);
document.addEventListener('submit',event=>{if(event.target.id!=='prospect-loss-form')return;event.preventDefault();const l=byId('leads',event.target.dataset.id),reason=new FormData(event.target).get('reason').trim();if(!l||reason.length<8)return;const previous=l.stage;l.stage='Lost';l.lossReason=reason;(l.history||(l.history=[])).push({at:new Date().toLocaleString('en-IN'),text:`Stage: ${previous} → Lost · ${reason}`});save();$('#modal-root').innerHTML='';render();toast('Prospect marked lost.');},true);
document.addEventListener('dragstart',event=>{const card=event.target.closest('.prospect-card');if(!card)return;event.dataTransfer.setData('application/x-prospect-id',card.dataset.prospectId);event.dataTransfer.effectAllowed='move';card.classList.add('dragging');},true);
document.addEventListener('dragend',event=>event.target.closest('.prospect-card')?.classList.remove('dragging'),true);
document.addEventListener('dragover',event=>{const lane=event.target.closest('[data-prospect-stage]');if(lane&&lane.dataset.prospectStage!=='Converted'){event.preventDefault();lane.classList.add('drag-over');}},true);
document.addEventListener('dragleave',event=>{const lane=event.target.closest('[data-prospect-stage]');if(lane&&!lane.contains(event.relatedTarget))lane.classList.remove('drag-over');},true);
document.addEventListener('drop',event=>{const lane=event.target.closest('[data-prospect-stage]');if(!lane)return;event.preventDefault();lane.classList.remove('drag-over');const id=event.dataTransfer.getData('application/x-prospect-id');if(lane.dataset.prospectStage==='Converted'){toast('Use Convert to Client from the prospect profile.');return;}prospectHubMove(id,lane.dataset.prospectStage);},true);
document.addEventListener('click',event=>{const action=event.target.closest('[data-prospect-action]')?.dataset.prospectAction;if(action==='list-prev'){prospectListPage=Math.max(1,prospectListPage-1);render();}if(action==='list-next'){prospectListPage++;render();}},true);
document.addEventListener('change',event=>{if(event.target.dataset.prospectChange==='list-sort'){prospectListSort=event.target.value;prospectListPage=1;render();}if(event.target.dataset.prospectChange==='list-size'){prospectListPageSize=Number(event.target.value);prospectListPage=1;render();}},true);
document.addEventListener("click",event=>{const action=event.target.closest("[data-prospect-action]")?.dataset.prospectAction;if(action==="fullscreen"){prospectFullscreen=!prospectFullscreen;document.body.classList.toggle("prospect-fullscreen",prospectFullscreen);render();}const nav=event.target.closest("[data-view]");if(nav&&nav.dataset.view!=="prospects"){prospectFullscreen=false;document.body.classList.remove("prospect-fullscreen");}},true);document.addEventListener("keydown",event=>{if(event.key==="Escape"&&prospectFullscreen){prospectFullscreen=false;document.body.classList.remove("prospect-fullscreen");render();}},true);
document.addEventListener('submit',event=>{
 if(event.target.id!=='prospect-save-view-form')return;
 event.preventDefault();
 const name=new FormData(event.target).get('name')?.trim();
 if(!name)return;
 state.prospectViews.push({id:uid('view'),name:name.slice(0,40),query:prospectHubQuery,owner:prospectHubOwner,sort:prospectHubSort,followup:prospectHubFollowup});
 save();$('#modal-root').innerHTML='';render();toast('Prospect view saved.');
},true);
